mapper.select:
SELECT OutAmt.코드 As outputCode, OutAmt.날짜 as outputDate, OutAmt.금액 as outputAmt, OutAmt.비고 as outputCnt, OutAmt.계정코드1 as outputFlCode1, OutAmt.계정코드2 as outputFlCode2, OutAmt.계정코드3 as outputFlCode3, OutAmt.코드분류 As codeType, CoutConf1.관 As outputFlNm1, CoutConf2.항 As outputFlNm2, CoutConf3.목 As outputFlNm3, OutAmt.년도 As year, OutAmt.성도코드 As outputNameCode, OutAmt.이름 As outputName FROM 지출 OutAmt, 지출관 CoutConf1, 지출항 CoutConf2, 지출목 CoutConf3 Where OutAmt.계정코드1 = CoutConf1.관코드 AND OutAmt.코드분류 = CoutConf1.코드분류 AND OutAmt.계정코드1 = CoutConf2.관코드 AND OutAmt.계정코드2 = CoutConf2.항코드 AND OutAmt.코드분류 = CoutConf2.코드분류 AND OutAmt.계정코드1 = CoutConf3.관코드 AND OutAmt.계정코드2 = CoutConf3.항코드 AND OutAmt.계정코드3 = CoutConf3.목코드 AND OutAmt.코드분류 = CoutConf3.코드분류
AND OutAmt.코드분류 = #{codeType}
AND OutAmt.년도 = #{year}
AND OutAmt.코드 = #{outputCode}
AND OutAmt.코드 = (Select Max(코드) From 지출)

SELECT OutAmt.코드 As outputCode, OutAmt.날짜 as outputDate, OutAmt.금액 as outputAmt, OutAmt.비고 as outputCnt, OutAmt.계정코드1 as outputFlCode1, OutAmt.계정코드2 as outputFlCode2, OutAmt.계정코드3 as outputFlCode3, OutAmt.코드분류 As codeType, CoutConf1.관 As outputFlNm1, CoutConf2.항 As outputFlNm2, CoutConf3.목 As outputFlNm3, OutAmt.년도 As year, OutAmt.성도코드 As outputNameCode, OutAmt.이름 As outputName FROM 지출 OutAmt, 지출관 CoutConf1, 지출항 CoutConf2, 지출목 CoutConf3 Where OutAmt.계정코드1 = CoutConf1.관코드 AND OutAmt.코드분류 = CoutConf1.코드분류 AND OutAmt.계정코드1 = CoutConf2.관코드 AND OutAmt.계정코드2 = CoutConf2.항코드 AND OutAmt.코드분류 = CoutConf2.코드분류 AND OutAmt.계정코드1 = CoutConf3.관코드 AND OutAmt.계정코드2 = CoutConf3.항코드 AND OutAmt.계정코드3 = CoutConf3.목코드 AND OutAmt.코드분류 = CoutConf3.코드분류
AND OutAmt.코드분류 = #{codeGb}
AND OutAmt.년도 = #{year}
AND OutAmt.코드 = #{outputCode}
AND OutAmt.비고 Like '%'||#{outputCnt}||'%'
AND OutAmt.날짜 >= #{fmOutputDate}
AND OutAmt.날짜 <= #{toOutputDate}
AND OutAmt.계정코드1 = #{outputFlCode1}
AND OutAmt.계정코드2 = #{outputFlCode2}
AND OutAmt.계정코드3 = #{outputFlCode3}
AND OutAmt.성도코드1 = #{outputNameCode1}
AND OutAmt.이름1 = #{outputName1}
Order by OutAmt.날짜, OutAmt.코드 desc
